class TokenFunctor[A](protected val _value: A) {
  def map[B](f: A => B): TokenFunctor[B] = new TokenFunctor(f(_value))

  def flatMap[B](f: A => TokenFunctor[B]): TokenFunctor[B] = f(_value)

  def getOrElse(default: => A): A = 
    if (_value != null) _value else default

  def get: A = _value
}

object TokenFunctor {
  def apply[A](value: A): TokenFunctor[A] = new TokenFunctor(value)
}

class TokenMonad[A](value: A) extends TokenFunctor[A](value) {
  def ap[B](funcWrapped: TokenMonad[A => B]): TokenMonad[B] =
    new TokenMonad(funcWrapped._value(this._value))
}

object TokenMonad {
  def pure[A](value: A): TokenMonad[A] = new TokenMonad(value)
  def apply[A](value: A): TokenMonad[A] = pure(value)
}

