sealed trait JsonValue
object JsonValue {
  case class JsonString(value: String) extends JsonValue
  case class JsonNumber(value: BigDecimal) extends JsonValue
  case class JsonBool(value: Boolean) extends JsonValue
  case object JsonNull extends JsonValue
  case class JsonArray(values: List[JsonValue]) extends JsonValue
  case class JsonObject(fields: Map[String, JsonValue]) extends JsonValue

  def stringify(jv: JsonValue, pretty: Boolean = false, indent: Int = 0): String = {
    val spaces = if (pretty) "  " * indent else ""
    val newline = if (pretty) "\n" else ""
    val sep = if (pretty) ", " else ","

    jv match {
      case JsonString(s) => s"\"${escapeString(s)}\""
      case JsonNumber(n) => n.toString
      case JsonBool(b) => b.toString
      case JsonNull => "null"
      case JsonArray(values) =>
        if (values.isEmpty) "[]"
        else if (pretty) {
          val items = values.map(v => "  " * (indent + 1) + stringify(v, pretty, indent + 1))
          s"[$newline${items.mkString("," + newline)}$newline$spaces]"
        } else {
          values.map(v => stringify(v, pretty, indent)).mkString("[", sep, "]")
        }
      case JsonObject(fields) =>
        if (fields.isEmpty) "{}"
        else if (pretty) {
          val items = fields.map { case (k, v) =>
            "  " * (indent + 1) + s"\"$k\": ${stringify(v, pretty, indent + 1)}"
          }
          s"{$newline${items.mkString("," + newline)}$newline$spaces}"
        } else {
          fields.map { case (k, v) => s"\"$k\":${stringify(v, pretty, indent)}" }.mkString("{", sep, "}")
        }
    }
  }

  private def escapeString(s: String): String =
    s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t")
}

class JsonTokenizer(pretty: Boolean = false) {
  import JsonValue._

  def tokenize(value: JsonValue): Token = {
    val jsonStr = stringify(value, pretty)
    Token(jsonStr, TokenType.Structured, Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.").toList

    def extract(current: JsonValue, remaining: List[String]): Option[JsonValue] = {
      remaining match {
        case Nil => Some(current)
        case head :: tail =>
          current match {
            case JsonObject(fields) =>
              fields.get(head).flatMap(v => extract(v, tail))
            case JsonArray(values) =>
              Try(head.toInt).toOption.flatMap { idx =>
                values.lift(idx).flatMap(v => extract(v, tail))
              }
            case _ => None
          }
      }
    }

    extract(value, parts).map(tokenize)
  }
}

object JsonTokenizer {
  def apply(pretty: Boolean = false): JsonTokenizer = new JsonTokenizer(pretty)
}

